def versiones_e_informes_existentes(apps, schema_editor):
    """Las propuestas ya enviadas quedan como versión 1, y el levantamiento ya registrado como informe."""
    Ficha = apps.get_model("comercial", "FichaComercial")
    Version = apps.get_model("comercial", "PropuestaVersion")
    Informe = apps.get_model("comercial", "InformeRequerimiento")
    Adjunto = apps.get_model("tickets", "Adjunto")
    estado = {"aprobada": "aprobada", "instalacion": "aprobada", "rechazada": "rechazada"}
    for f in Ficha.objects.all():
        if f.fecha_envio:
            Version.objects.create(
                ficha=f, numero=1, valor=f.valor_propuesta, enviada=f.fecha_envio, respondida=f.fecha_respuesta,
                archivo=Adjunto.objects.filter(ticket_id=f.ticket_id, es_propuesta=True).order_by("-creado").first(),
                estado=estado.get(f.etapa, "enviada"), motivo=f.motivo_rechazo,
            )
        if f.levantamiento.strip():
            Informe.objects.create(ficha=f, con_visita=True, necesidad=f.levantamiento, materiales=f.levantamiento)


